import { DEFAULT_SEPARATOR } from './atlas'
import type { IGeneratedTextureData, IPalettePermutation, IPaletteSetData } from './types'

declare global {
	// @ts-expect-error - Broken BB types
	interface Texture {
		/** Set on a texture generated by a Permutation Set. Empty on every other texture. */
		palette_generated: IGeneratedTextureData | Record<string, never>
	}
	// @ts-expect-error - Broken BB types
	interface TextureGroup {
		/** Set on a Permutation Set's group. Empty on every other group. */
		palette_set: IPaletteSetData | Record<string, never>
	}
}

/** A Permutation Set: a texture group holding the set's data, with its recolors inside. */
export type PaletteSet = TextureGroup & { palette_set: IPaletteSetData }
export type GeneratedTexture = Texture & { palette_generated: IGeneratedTextureData }

/** Sets with at least this many recolors start folded, so they don't flood the panel. */
const FOLD_THRESHOLD = 16

export function isPaletteSet(group: TextureGroup | undefined | null | false): group is PaletteSet {
	return !!group && Array.isArray((group.palette_set as IPaletteSetData)?.permutations)
}

export function isGeneratedTexture(
	texture: Texture | undefined | null | false
): texture is GeneratedTexture {
	return (
		!!texture && typeof (texture.palette_generated as IGeneratedTextureData)?.set === 'string'
	)
}

/** Whether a texture is managed by a Permutation Set, so it has no image of its own to edit. */
export function isPaletteTexture(texture: Texture | undefined | null | false): boolean {
	return isGeneratedTexture(texture)
}

export function isReferenceSet(set: PaletteSet): boolean {
	return !!set.palette_set.reference
}

export function getPaletteSets(): PaletteSet[] {
	return TextureGroup.all.filter(isPaletteSet)
}

export function getPaletteSet(uuid: string): PaletteSet | undefined {
	const group = TextureGroup.all.find(g => g.uuid === uuid)
	return isPaletteSet(group) ? group : undefined
}

export function getGeneratedTextures(set: PaletteSet): GeneratedTexture[] {
	return Texture.all.filter(
		(t): t is GeneratedTexture => isGeneratedTexture(t) && t.palette_generated.set === set.uuid
	)
}

/** A project set's base textures that still exist, in order. */
export function getBaseTextures(set: PaletteSet): Texture[] {
	if (isReferenceSet(set)) return []
	return set.palette_set.bases
		.map(uuid => Texture.all.find(t => t.uuid === uuid))
		.filter((t): t is Texture => !!t && !isPaletteTexture(t))
}

export interface IGeneratedSource {
	set: PaletteSet
	/** The base's texture UUID (project sets) or texture id (reference sets). */
	base: string
	/** The base Texture, for project sets. */
	baseTexture?: Texture
	permutation: IPalettePermutation
}

/** What a generated texture recolors, or undefined if its set, base or permutation is gone. */
export function getGeneratedSource(texture: Texture): IGeneratedSource | undefined {
	if (!isGeneratedTexture(texture)) return undefined
	const { set: setUuid, base, permutation: permutationUuid } = texture.palette_generated
	const set = getPaletteSet(setUuid)
	if (!set || !set.palette_set.bases.includes(base)) return undefined
	const permutation = set.palette_set.permutations.find(p => p.uuid === permutationUuid)
	if (!permutation) return undefined
	if (isReferenceSet(set)) return { set, base, permutation }
	const baseTexture = getBaseTextures(set).find(t => t.uuid === base)
	return baseTexture ? { set, base, baseTexture, permutation } : undefined
}

/**
 * The texture painting on `texture` should edit: a project set's generated texture paints its
 * base, so every colorway updates. Hosts chain this after their own redirects.
 */
export function getPaintTarget(texture: Texture): Texture {
	return getGeneratedSource(texture)?.baseTexture ?? texture
}

/** The name a base gets in generated texture names: its texture name, or its id's last part. */
export function getBaseLabel(set: PaletteSet | IPaletteSetData, base: string): string {
	const data = 'palette_set' in set ? set.palette_set : set
	if (data.reference) return base.slice(base.lastIndexOf('/') + 1).replace(/^.*:/, '')
	const texture = Texture.all.find(t => t.uuid === base)
	return (texture?.name ?? base).replace(/\.png$/i, '')
}

export function createSetData(overrides: Partial<IPaletteSetData> = {}): IPaletteSetData {
	return {
		separator: DEFAULT_SEPARATOR,
		bases: [],
		key: { colors: [] },
		permutations: [],
		...overrides,
	}
}

const generatedKey = (base: string, permutation: string) => `${base}\n${permutation}`

/**
 * Creates, renames and removes the set's generated textures to match its bases and permutations.
 * Faces on a removed texture move to its base, or lose their texture for reference sets. Call
 * inside an Undo edit that covers the set's textures and the returned cubes.
 */
function syncGeneratedTextures(set: PaletteSet, cubes: Cube[]) {
	const data = set.palette_set
	const existing = new Map(
		getGeneratedTextures(set).map(t => [
			generatedKey(t.palette_generated.base, t.palette_generated.permutation),
			t,
		])
	)
	const bases = isReferenceSet(set) ? data.bases : getBaseTextures(set).map(t => t.uuid)
	const kept: Texture[] = []

	for (const base of bases) {
		for (const permutation of data.permutations) {
			const key = generatedKey(base, permutation.uuid)
			const name = getBaseLabel(set, base) + data.separator + permutation.suffix
			let texture = existing.get(key)
			if (texture) {
				existing.delete(key)
				texture.name = name
			} else {
				texture = new Texture({ name, group: set.uuid }).add(false) as GeneratedTexture
				texture.palette_generated = { set: set.uuid, base, permutation: permutation.uuid }
				texture.internal = true
				texture.saved = true
			}
			kept.push(texture)
		}
	}

	for (const texture of existing.values()) {
		const { base } = texture.palette_generated
		const fallback = isReferenceSet(set) ? false : base
		for (const cube of cubes) {
			for (const face of Object.values(cube.faces)) {
				if (face.texture === texture.uuid) face.texture = fallback
			}
		}
		texture.remove(true)
	}

	arrangeGeneratedTextures()
	return kept
}

/**
 * Orders each set's generated textures by base, then permutation. Undo re-adds removed textures at
 * the end, so this also runs after undo and redo.
 */
export function arrangeGeneratedTextures() {
	for (const set of getPaletteSets()) {
		const { bases, permutations } = set.palette_set
		const order = (t: GeneratedTexture) =>
			bases.indexOf(t.palette_generated.base) * permutations.length +
			permutations.findIndex(p => p.uuid === t.palette_generated.permutation)
		const generated = getGeneratedTextures(set)
		if (!generated.length) continue
		const index = Math.min(...generated.map(t => Texture.all.indexOf(t)))
		for (const texture of generated) Texture.all.remove(texture)
		Texture.all.splice(index, 0, ...generated.sort((a, b) => order(a) - order(b)))
	}
}

/**
 * Keeps each set's group holding exactly its recolors: recolors dragged out go back, and other
 * textures dragged or imported in move out. Returns whether anything moved.
 */
export function repairSetGroups(): boolean {
	let moved = false
	for (const texture of Texture.all) {
		const group = TextureGroup.all.find(g => g.uuid === texture.group)
		if (isGeneratedTexture(texture)) {
			const set = getPaletteSet(texture.palette_generated.set)
			if (set && texture.group !== set.uuid) {
				texture.group = set.uuid
				moved = true
			}
		} else if (isPaletteSet(group)) {
			texture.group = ''
			moved = true
		}
	}
	return moved
}

/** Cubes with a face on any of `textures`. */
export function getCubesUsing(textures: Texture[]): Cube[] {
	const uuids = new Set(textures.map(t => t.uuid))
	return Cube.all.filter(cube =>
		Object.values(cube.faces).some(face => uuids.has(face.texture as string))
	)
}

/**
 * Replaces a set's data and name, and brings its generated textures in line, as one undo step.
 */
export function editPaletteSet(set: PaletteSet, data: IPaletteSetData, name = set.name) {
	const before = getGeneratedTextures(set)
	const cubes = getCubesUsing(before)
	Undo.initEdit({ texture_groups: [set], textures: before, elements: cubes, uv_only: true })
	set.name = name
	set.palette_set = structuredClone(data)
	const after = syncGeneratedTextures(set, cubes)
	Undo.finishEdit('Edit permutation set', {
		texture_groups: [set],
		textures: after,
		elements: cubes,
		uv_only: true,
	})
	Canvas.updateAllFaces()
}

/** Creates a Permutation Set and its generated textures, as one undo step. */
export function createPaletteSet(name: string, data: IPaletteSetData): PaletteSet {
	Undo.initEdit({ texture_groups: [], textures: [] })
	const set = new TextureGroup({ name }).add() as PaletteSet
	set.palette_set = structuredClone(data)
	const generated = syncGeneratedTextures(set, [])
	set.folded = generated.length >= FOLD_THRESHOLD
	Undo.finishEdit('Create permutation set', { texture_groups: [set], textures: generated })
	return set
}

/** Whether removing `textures` affects a Permutation Set, as a recolor or a project set's base. */
export function affectsPaletteSets(textures: Texture[]): boolean {
	const uuids = new Set(textures.map(t => t.uuid))
	return (
		textures.some(isPaletteTexture) ||
		getPaletteSets().some(
			set => !isReferenceSet(set) && set.palette_set.bases.some(b => uuids.has(b))
		)
	)
}

/**
 * Recolors in `textures` that can't be removed on their own: ones whose set and base both stay.
 * They come from their set, so they're removed by editing or deleting the set instead.
 */
export function getProtectedRecolors(textures: Texture[]): GeneratedTexture[] {
	const uuids = new Set(textures.map(t => t.uuid))
	return textures.filter(
		(t): t is GeneratedTexture =>
			isGeneratedTexture(t) &&
			!!getPaletteSet(t.palette_generated.set) &&
			!uuids.has(t.palette_generated.base)
	)
}

export interface ITextureRemoval {
	/** The textures to remove, plus what depends on them. */
	removed: Texture[]
	/** Sets removed along with their recolors. */
	removedSets: PaletteSet[]
	/** Project sets that lose a base. */
	touchedSets: PaletteSet[]
}

/**
 * What removing `textures` and `sets` takes with it: each removed set's recolors, and each removed
 * base's recolors, whose set then loses that base.
 */
export function planTextureRemoval(textures: Texture[], sets: PaletteSet[] = []): ITextureRemoval {
	const uuids = new Set([...textures, ...sets].map(t => t.uuid))
	const generated = Texture.all.filter(
		(t): t is GeneratedTexture =>
			isGeneratedTexture(t) &&
			!uuids.has(t.uuid) &&
			(uuids.has(t.palette_generated.set) || uuids.has(t.palette_generated.base))
	)
	return {
		removed: [...textures, ...generated],
		removedSets: sets,
		touchedSets: getPaletteSets().filter(
			set => !uuids.has(set.uuid) && set.palette_set.bases.some(b => uuids.has(b))
		),
	}
}

/** The Undo aspects a planned removal touches, before and after it's applied. */
export function getRemovalUndoAspects(removal: ITextureRemoval, cubes: Cube[]) {
	return {
		before: {
			textures: removal.removed,
			texture_groups: [...removal.removedSets, ...removal.touchedSets],
			elements: cubes,
			uv_only: true,
		},
		after: {
			textures: [],
			texture_groups: removal.touchedSets,
			elements: cubes,
			uv_only: true,
		},
	}
}

/**
 * Carries out a planned removal without an undo step: faces on a removed generated texture move to
 * its base if the base stays, other faces on removed textures lose their texture, and touched sets
 * drop their removed bases. Call inside an Undo edit made from {@link getRemovalUndoAspects}, with
 * `cubes` covering every cube using a removed texture.
 */
export function applyTextureRemoval(removal: ITextureRemoval, cubes: Cube[]) {
	const uuids = new Set(removal.removed.map(t => t.uuid))
	const removedSets = new Set(removal.removedSets.map(set => set.uuid))
	const fallbacks = new Map<string, string | false>()
	for (const texture of removal.removed) {
		if (!isGeneratedTexture(texture)) continue
		const set = getPaletteSet(texture.palette_generated.set)
		const { base } = texture.palette_generated
		const keepsBase = set && !isReferenceSet(set) && !uuids.has(base)
		fallbacks.set(texture.uuid, keepsBase ? base : false)
	}
	for (const cube of cubes) {
		for (const face of Object.values(cube.faces)) {
			const texture = face.texture as string
			if (uuids.has(texture)) face.texture = fallbacks.get(texture) ?? false
		}
	}
	for (const set of removal.touchedSets) {
		set.palette_set.bases = set.palette_set.bases.filter(b => !uuids.has(b))
	}
	for (const texture of removal.removed) texture.remove(true)
	for (const set of TextureGroup.all.filter(g => removedSets.has(g.uuid))) set.remove()
}

/** Removes `textures` and `sets` with everything {@link planTextureRemoval} finds, in one undo step. */
export function removeTextures(textures: Texture[], sets: PaletteSet[] = []) {
	const removal = planTextureRemoval(textures, sets)
	const cubes = getCubesUsing(removal.removed)
	const aspects = getRemovalUndoAspects(removal, cubes)
	Undo.initEdit(aspects.before)
	applyTextureRemoval(removal, cubes)
	Undo.finishEdit(sets.length ? 'Delete permutation set' : 'Remove texture', aspects.after)
	Canvas.updateAllFaces()
}
